import pandas as pd
import numpy as np
import os
from collections import Counter
from sklearn.model_selection import train_test_split

# Create submission directory if not exists
os.makedirs("./submission", exist_ok=True)

# Load training and test data
print("Loading data...")
train_df = pd.read_csv("./input/en_train.csv")
test_df = pd.read_csv("./input/en_test.csv")

# For validation, split training data
print("Creating validation split...")
valid_fraction = 0.2
train_subset, val_subset = train_test_split(
    train_df, test_size=valid_fraction, random_state=42, stratify=train_df["class"]
)

# Build frequency table with contextual information (tri-grams)
print("Building contextual lookup table...")
context_table = {}  # {(prev_token, current_token, next_token): [after_values]}

# Add sentence boundaries markers
sentences_by_id = {}
for _, row in train_subset.iterrows():
    sent_id = row["sentence_id"]
    tok_id = row["token_id"]
    if sent_id not in sentences_by_id:
        sentences_by_id[sent_id] = []
    sentences_by_id[sent_id].append((tok_id, row["before"], row["after"]))

# Sort tokens by token_id within each sentence
for sent_id in sentences_by_id:
    sentences_by_id[sent_id].sort(key=lambda x: x[0])

# Extract contextual patterns
for sent_id, tokens in sentences_by_id.items():
    for i, (tok_id, before, after) in enumerate(tokens):
        prev_tok = tokens[i - 1][1] if i > 0 else "<BOS>"
        next_tok = tokens[i + 1][1] if i < len(tokens) - 1 else "<EOS>"

        key = (prev_tok, before, next_tok)
        if key not in context_table:
            context_table[key] = []
        context_table[key].append(after)

# Get most common after for each context
best_after_context = {
    k: Counter(v).most_common(1)[0][0] for k, v in context_table.items()
}

# Also build single token lookup as fallback
single_token_lookup = {}
for before, after in zip(train_subset["before"], train_subset["after"]):
    if before not in single_token_lookup:
        single_token_lookup[before] = []
    single_token_lookup[before].append(after)

best_after_single = {
    k: Counter(v).most_common(1)[0][0] for k, v in single_token_lookup.items()
}


# Function to get prediction with context
def predict(before_token, prev_token=None, next_token=None):
    # Try full tri-gram context first
    if prev_token is not None and next_token is not None:
        key = (prev_token, before_token, next_token)
        if key in best_after_context:
            return best_after_context[key]

    # Try bigram with prev token
    if prev_token is not None:
        key = (prev_token, before_token, "<EOS>")
        if key in best_after_context:
            return best_after_context[key]

    # Try bigram with next token
    if next_token is not None:
        key = ("<BOS>", before_token, next_token)
        if key in best_after_context:
            return best_after_context[key]

    # Fallback to single token
    return best_after_single.get(before_token, before_token)


# Evaluate on validation set using same contextual approach
print("Evaluating on validation set...")
val_sentences_by_id = {}
for _, row in val_subset.iterrows():
    sent_id = row["sentence_id"]
    if sent_id not in val_sentences_by_id:
        val_sentences_by_id[sent_id] = []
    val_sentences_by_id[sent_id].append((row["token_id"], row["before"], row["after"]))

for sent_id in val_sentences_by_id:
    val_sentences_by_id[sent_id].sort(key=lambda x: x[0])

val_predictions = []
val_true = []

for sent_id, tokens in val_sentences_by_id.items():
    for i, (tok_id, before, after) in enumerate(tokens):
        prev_tok = tokens[i - 1][1] if i > 0 else "<BOS>"
        next_tok = tokens[i + 1][1] if i < len(tokens) - 1 else "<EOS>"

        pred = predict(before, prev_tok, next_tok)
        val_predictions.append(pred)
        val_true.append(after)

matches = sum(p == t for p, t in zip(val_predictions, val_true))
accuracy = matches / len(val_true)
print(f"Validation Accuracy: {accuracy:.6f}")

# Generate predictions for test set
print("Generating test predictions...")
test_sentences_by_id = {}
for idx, row in test_df.iterrows():
    sent_id = row["sentence_id"]
    if sent_id not in test_sentences_by_id:
        test_sentences_by_id[sent_id] = []
    test_sentences_by_id[sent_id].append(
        {"idx": idx, "token_id": row["token_id"], "before": row["before"]}
    )

for sent_id in test_sentences_by_id:
    test_sentences_by_id[sent_id].sort(key=lambda x: x["token_id"])

test_predictions = [""] * len(test_df)

for sent_id, tokens in test_sentences_by_id.items():
    for i, tok_info in enumerate(tokens):
        before = tok_info["before"]
        idx = tok_info["idx"]

        prev_tok = tokens[i - 1]["before"] if i > 0 else "<BOS>"
        next_tok = tokens[i + 1]["before"] if i < len(tokens) - 1 else "<EOS>"

        pred = predict(before, prev_tok, next_tok)
        test_predictions[idx] = pred

# Create submission dataframe
id_col = [
    f"{sid}_{tid}" for sid, tid in zip(test_df["sentence_id"], test_df["token_id"])
]
submission_df = pd.DataFrame({"id": id_col, "after": test_predictions})

# Save submission
submission_df.to_csv("./submission/submission.csv", index=False)
print(f"Submission saved to ./submission/submission.csv")
print(f"Total predictions: {len(submission_df)}")

# Verify format against sample
sample_submission = pd.read_csv("./input/en_sample_submission.csv")
print(f"Sample submission columns: {sample_submission.columns.tolist()}")
print(
    f"Expected rows: {len(sample_submission)}, Predictions made: {len(submission_df)}"
)
